mapper.select:
SELECT r.id, r.receive_no, r.apply_emp_id, r.dept_id, r.receive_date, r.receive_reason, r.create_time, r.operator_code, r.update_time, COALESCE(e1.emp_name, '') AS apply_emp_name, COALESCE(e1.emp_code, '') AS apply_emp_code, COALESCE(d.dept_name, '') AS dept_name, COALESCE(e2.emp_name, '') AS operator_name FROM asset_receive_main r LEFT JOIN sys_emp e1 ON r.apply_emp_id = CAST(e1.emp_id AS CHAR) LEFT JOIN sys_dept d ON r.dept_id = d.dept_id LEFT JOIN sys_emp e2 ON r.operator_code = e2.emp_code WHERE 1=1
AND r.receive_no LIKE CONCAT('%', #{receiveNo}, '%')
AND r.dept_id = #{deptId}
AND r.apply_emp_id = #{applyEmpId}
AND r.operator_code = #{operatorCode}
ORDER BY r.create_time DESC
